import { test } from "node:test";
import assert from "node:assert/strict";
import { createQueue } from "../src/jobs/queue.js";
import { createHandlers } from "../src/jobs/handlers.js";
import { Worker } from "../src/jobs/worker.js";

function setup({ renderFailures = new Set() } = {}) {
  const queue = createQueue({ maxAttempts: 3 });
  const sent = [];
  const logs = [];
  const renders = [];
  const renderer = {
    async render(id) {
      renders.push(id);
      if (renderFailures.has(id)) throw new Error(`renderer timeout for ${id}`);
      return Buffer.from(`%PDF-${id}`);
    },
    async discard() {},
  };
  const mailer = {
    async send(to, subject) {
      sent.push({ to, subject });
    },
  };
  const logger = { error: (m) => logs.push(m) };
  const worker = new Worker({ queue, handlers: createHandlers({ renderer, mailer }), logger });
  return { queue, worker, sent, logs, renders };
}

test("a successful job is acked, mailed and reported as processed", async () => {
  const { queue, worker, sent } = setup();
  const id = queue.enqueue("invoice.send", { invoiceId: "inv-1", email: "a@x.io" });
  const processed = [];
  worker.on("processed", (jobId) => processed.push(jobId));
  await worker.drain();
  assert.equal(queue.get(id).status, "done");
  assert.deepEqual(sent, [{ to: "a@x.io", subject: "Invoice inv-1" }]);
  assert.deepEqual(processed, [id]);
});

test("a failed job is not acked: it goes back to pending for a retry", async () => {
  const { queue, worker } = setup({ renderFailures: new Set(["inv-2"]) });
  const id = queue.enqueue("invoice.send", { invoiceId: "inv-2", email: "b@x.io" });
  await worker.processNext();
  console.log("job after first failed attempt:", queue.get(id));
  assert.equal(queue.get(id).status, "pending", "failed job must be nacked, not acked");
  assert.equal(queue.get(id).lastError, "renderer timeout for inv-2");
});

test("a failed job emits 'failed' with the reason and does not emit 'processed'", async () => {
  const { queue, worker } = setup({ renderFailures: new Set(["inv-3"]) });
  queue.enqueue("invoice.send", { invoiceId: "inv-3", email: "c@x.io" });
  const failed = [];
  const processed = [];
  worker.on("failed", (e) => failed.push(e));
  worker.on("processed", (e) => processed.push(e));
  await worker.processNext();
  assert.deepEqual(processed, []);
  assert.equal(failed.length, 1);
  assert.equal(failed[0].error, "renderer timeout for inv-3");
});

test("a job that keeps failing is retried then dead-lettered after maxAttempts", async () => {
  const { queue, worker, renders } = setup({ renderFailures: new Set(["inv-4"]) });
  const id = queue.enqueue("invoice.send", { invoiceId: "inv-4", email: "d@x.io" });
  await worker.drain();
  assert.equal(renders.length, 3, "the renderer should have been tried 3 times");
  assert.equal(queue.get(id).status, "dead");
  assert.equal(queue.stats().dead, 1);
});

test("a failing job does not stop later jobs", async () => {
  const { queue, worker, sent } = setup({ renderFailures: new Set(["bad"]) });
  queue.enqueue("invoice.send", { invoiceId: "bad", email: "x@x.io" });
  const good = queue.enqueue("invoice.send", { invoiceId: "good", email: "y@x.io" });
  await worker.drain();
  assert.equal(queue.get(good).status, "done");
  assert.deepEqual(sent.map((s) => s.to), ["y@x.io"]);
});

test("an unknown job type ends up dead, not done", async () => {
  const { queue, worker } = setup();
  const id = queue.enqueue("invoice.archive", { invoiceId: "inv-5" });
  await worker.drain();
  assert.equal(queue.get(id).status, "dead");
});

test("failures are logged with the job id", async () => {
  const { queue, worker, logs } = setup({ renderFailures: new Set(["inv-6"]) });
  const id = queue.enqueue("invoice.send", { invoiceId: "inv-6", email: "e@x.io" });
  await worker.processNext();
  assert.ok(logs.some((l) => l.includes(id) && l.includes("renderer timeout")), `log lines: ${logs}`);
});
